// Idempotency guard
if (document.getElementById('__global-en-resources-panel__')) return;

// Extract the current search query from the search input
const inputEl = document.querySelector('input[name="text"]');
const query = inputEl ? inputEl.value.trim() : '';
const encoded = encodeURIComponent(query);

// Build source links
const sources = [
  {
    name: 'Wikipedia',
    icon: 'https://en.wikipedia.org/favicon.ico',
    url: 'https://en.wikipedia.org/w/index.php?search=' + encoded,
    color: '#e8f4fd',
    border: '#4a90d9',
    label: 'English encyclopedia'
  },
  {
    name: 'Medium',
    icon: 'https://medium.com/favicon.ico',
    url: 'https://medium.com/search?q=' + encoded,
    color: '#f0faf0',
    border: '#28a745',
    label: 'Articles & blogs'
  },
  {
    name: 'LinkedIn',
    icon: 'https://static.licdn.com/sc/h/al2o9zrvru7aqj8e1x2rzsrca',
    url: 'https://www.linkedin.com/search/results/all/?keywords=' + encoded,
    color: '#eaf3fb',
    border: '#0077b5',
    label: 'Professional network'
  }
];

// Create the container <li>
const li = document.createElement('li');
li.id = '__global-en-resources-panel__';
li.style.cssText = 'list-style:none;margin:0 0 16px 0;padding:0;';

const cards = sources.map(function(s) {
  return '<a href="' + s.url + '" target="_blank" rel="noopener noreferrer" '
    + 'style="display:flex;flex-direction:column;justify-content:space-between;flex:1 1 0;min-width:0;'
    + 'background:' + s.color + ';border:1.5px solid ' + s.border + ';border-radius:12px;'
    + 'padding:14px 16px;text-decoration:none;color:inherit;cursor:pointer;" '
    + 'onmouseenter="this.style.boxShadow=\'0 4px 16px rgba(0,0,0,0.13)\';this.style.transform=\'translateY(-2px)\'" '
    + 'onmouseleave="this.style.boxShadow=\'none\';this.style.transform=\'translateY(0)\'">'
    + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;">'
    + '<img src="' + s.icon + '" alt="' + s.name + ' icon" style="width:20px;height:20px;border-radius:4px;flex-shrink:0;" onerror="this.style.display=\'none\'" />'
    + '<span style="font-size:15px;font-weight:700;color:#1a1a1a;">' + s.name + '</span>'
    + '</div>'
    + '<div style="font-size:12px;color:#555;margin-bottom:8px;">' + s.label + '</div>'
    + (query ? '<div style="font-size:13px;color:' + s.border + ';font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">🔍 &ldquo;' + query + '&rdquo;</div>' : '')
    + '</a>';
}).join('');

li.innerHTML = '<div style="background:#fff;border:2px solid #d0d7de;border-radius:14px;padding:14px 16px 16px;box-shadow:0 2px 8px rgba(0,0,0,0.07);">'
  + '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;">'
  + '<span style="font-size:16px;">🌐</span>'
  + '<span style="font-size:13px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;color:#5a6472;">Global English Resources</span>'
  + '</div>'
  + '<div style="display:flex;gap:10px;flex-wrap:nowrap;">' + cards + '</div>'
  + '</div>';

// Insert as the very first child of #search-result
element.insertBefore(li, element.firstChild);
